#!/usr/bin/env python3
"""
Context Engineering Reviewer for Claude 5 Models

Audits prompt setups against best practices from:
https://claude.com/blog/the-new-rules-of-context-engineering-for-claude-5-generation-models

Checks for:
1. Unnecessary complexity and redundancy
2. Constraint-based rules vs. judgment-based guidance
3. Progressive disclosure opportunities (skills/references)
4. Outdated patterns and over-specification
"""

import json
import re
import sys
from pathlib import Path
from typing import TypedDict, List, Dict, Any
from dataclasses import dataclass, asdict
from enum import Enum


class Severity(Enum):
    ERROR = "error"
    WARNING = "warning"
    INFO = "info"
    TIP = "tip"


@dataclass
class Finding:
    severity: str
    category: str
    line: int
    excerpt: str
    issue: str
    recommendation: str


class ContextReviewer:
    def __init__(self):
        self.findings: List[Finding] = []
        self.content = ""
        self.lines: List[str] = []

    def review_file(self, file_path: str) -> List[Finding]:
        """Review a single file for context engineering issues."""
        try:
            with open(file_path, "r") as f:
                self.content = f.read()
                self.lines = self.content.split("\n")
        except FileNotFoundError:
            return [Finding(
                severity=Severity.ERROR.value,
                category="file-error",
                line=0,
                excerpt="",
                issue=f"File not found: {file_path}",
                recommendation="Check the file path and try again."
            )]

        self.findings = []
        self._check_constraint_based_rules()
        self._check_redundancy()
        self._check_progressive_disclosure_opportunities()
        self._check_over_specification()
        self._check_outdated_patterns()

        return self.findings

    def _check_constraint_based_rules(self):
        """Find overly prescriptive rules that should be guidance."""
        constraint_patterns = [
            (r"NEVER\s+", "absolute prohibitions", "Consider judgment-based guidance instead"),
            (r"MUST\s+(NOT\s+)?", "hard requirements", "Frame as contextual principles"),
            (r"DO NOT\s+", "strict prohibitions", "Trust model reasoning with clear principles"),
            (r"ALWAYS\s+", "unconditional rules", "Use context-dependent guidance"),
            (r"You must\s+", "imperative rules", "Reframe as reasoning principles"),
        ]

        for i, line in enumerate(self.lines, 1):
            for pattern, rule_type, recommendation in constraint_patterns:
                if re.search(pattern, line, re.IGNORECASE):
                    self.findings.append(Finding(
                        severity=Severity.WARNING.value,
                        category="constraint-vs-judgment",
                        line=i,
                        excerpt=line.strip()[:80],
                        issue=f"Found {rule_type} instruction: '{pattern.strip()}'",
                        recommendation=f"{recommendation}. Example: instead of 'NEVER write X', try 'Write code that reads like the surrounding codebase.'"
                    ))

    def _check_redundancy(self):
        """Detect repeated instructions across the file."""
        patterns = [
            (r"don't.*comment", "comment guidance"),
            (r"write.*docstring", "docstring guidance"),
            (r"error.*handling", "error handling guidance"),
            (r"validation", "validation guidance"),
            (r"format", "formatting guidance"),
        ]

        instruction_counts: Dict[str, List[int]] = {}

        for i, line in enumerate(self.lines, 1):
            lower_line = line.lower()
            for pattern, category in patterns:
                if re.search(pattern, lower_line):
                    if category not in instruction_counts:
                        instruction_counts[category] = []
                    instruction_counts[category].append(i)

        for category, lines in instruction_counts.items():
            if len(lines) > 1:
                self.findings.append(Finding(
                    severity=Severity.INFO.value,
                    category="redundancy",
                    line=lines[0],
                    excerpt=f"'{category}' appears {len(lines)} times",
                    issue=f"'{category}' is mentioned on lines {', '.join(map(str, lines[:3]))}",
                    recommendation="Consider consolidating redundant instructions or moving them to a shared reference/skill."
                ))

    def _check_progressive_disclosure_opportunities(self):
        """Find content that could move to skills or references."""
        disclosure_patterns = [
            (r"## (Tool|Skill|Reference)", "section", "Move detailed tool/skill guidance to a dedicated skill or reference"),
            (r"### (Example|Pattern|Template)", "subsection", "Move examples/templates to references/ or dedicated skill"),
            (r"(Tool definition|parameters?|API spec)", "tool-spec", "Move detailed tool specs to a skill or reference, keep CLAUDE.md brief"),
        ]

        for i, line in enumerate(self.lines, 1):
            lower_line = line.lower()
            for pattern, pattern_type, recommendation in disclosure_patterns:
                if re.search(pattern, line, re.IGNORECASE):
                    self.findings.append(Finding(
                        severity=Severity.TIP.value,
                        category="progressive-disclosure",
                        line=i,
                        excerpt=line.strip()[:80],
                        issue=f"Detailed {pattern_type} content in main context",
                        recommendation=recommendation
                    ))

    def _check_over_specification(self):
        """Find unnecessarily detailed or prescriptive content."""
        over_spec_patterns = [
            (r"IMPORTANT.*:", "repeated emphasis markers", "Remove excessive emphasis; trust model attention"),
            (r"\*\*.*?\*\*.*\*\*.*?\*\*.*\*\*.*?\*\*", "excessive formatting", "Reduce markdown emphasis; one level per concept"),
            (r"(very\s+)?(carefully|important|critical)", "intensifying adverbs", "State requirements directly without intensifiers"),
        ]

        for i, line in enumerate(self.lines, 1):
            for pattern, issue_type, recommendation in over_spec_patterns:
                if re.search(pattern, line, re.IGNORECASE):
                    count = len(re.findall(pattern, line, re.IGNORECASE))
                    if count >= 2 or "IMPORTANT" in line:
                        self.findings.append(Finding(
                            severity=Severity.TIP.value,
                            category="over-specification",
                            line=i,
                            excerpt=line.strip()[:80],
                            issue=f"{issue_type} detected",
                            recommendation=recommendation
                        ))

    def _check_outdated_patterns(self):
        """Find patterns incompatible with Claude 5 best practices."""
        outdated = [
            (r"(provide.*examples?.*how to)", "teaching by example", "Let Claude 5 infer from good tool design instead"),
            (r"step.by.step|explicit.*instructions", "procedural guidance", "Claude 5 reasons better with principles; trim procedural detail"),
            (r"(explain|describe) what you're doing", "narration requirement", "Remove narration requirements; Claude 5 reasons better silently"),
        ]

        for i, line in enumerate(self.lines, 1):
            for pattern, pattern_name, recommendation in outdated:
                if re.search(pattern, line, re.IGNORECASE):
                    self.findings.append(Finding(
                        severity=Severity.INFO.value,
                        category="outdated-pattern",
                        line=i,
                        excerpt=line.strip()[:80],
                        issue=f"Outdated pattern (Claude 5): {pattern_name}",
                        recommendation=recommendation
                    ))


def format_report(findings: List[Finding]) -> str:
    """Format findings as a readable report."""
    if not findings:
        return "✓ No issues found. Your context setup looks good!"

    # Sort by severity
    severity_order = {Severity.ERROR.value: 0, Severity.WARNING.value: 1, Severity.INFO.value: 2, Severity.TIP.value: 3}
    findings_sorted = sorted(findings, key=lambda f: (severity_order.get(f.severity, 4), f.line))

    report = f"# Context Engineering Review\n\nFound {len(findings)} finding(s):\n\n"

    for finding in findings_sorted:
        icon = {"error": "❌", "warning": "⚠️", "info": "ℹ️", "tip": "💡"}
        report += f"{icon.get(finding.severity, '•')} **Line {finding.line}** [{finding.category}] {finding.severity.upper()}\n"
        report += f"  - Issue: {finding.issue}\n"
        report += f"  - Excerpt: `{finding.excerpt}`\n"
        report += f"  - Suggestion: {finding.recommendation}\n\n"

    summary = {}
    for finding in findings:
        summary[finding.severity] = summary.get(finding.severity, 0) + 1

    report += "## Summary\n"
    for severity in ["error", "warning", "info", "tip"]:
        if severity in summary:
            report += f"- {severity.capitalize()}s: {summary[severity]}\n"

    return report


def main():
    if len(sys.argv) < 2:
        print("Usage: context_reviewer.py <file_path>")
        sys.exit(1)

    file_path = sys.argv[1]
    reviewer = ContextReviewer()
    findings = reviewer.review_file(file_path)

    # Output as JSON or formatted report
    if "--json" in sys.argv:
        output = [asdict(f) for f in findings]
        print(json.dumps(output, indent=2))
    else:
        print(format_report(findings))


if __name__ == "__main__":
    main()

